INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_5203af6fe979','lineage_75e3399f4877','环境适应与演化 Family','牵头低成本的多样身体和行为搜索，从不同规则、初态和环境保留并扩张多种候选；研究身体生成参数与适应机制的变异和环境选择。与局部学习、研究点拓展并行协作，首批有趣形态和真实搜索分支、代际演化片段尽早接入动态形态墙，持续扩张。遵循 plan_13d78f0ae847 与 decision_66c4869fa1af 的当前版本；小网格、短程探索和共享训练资源起步。研究已启动，从现有成果继续，尊重暂停/停止且不重置一次性启动按钮。团队自主协作，不向建队者发送例行报告或常规请示。','',NULL,'',60,86400,false,'family_344be36e8a29','2026-10-15 23:37:56.286787+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_08db325e4051','lineage_8794980b1bb7','Portal 开源版本团队','本团队是 Portal 开发 Family 内的持续性子Family，负责跟随 Portal 主线开发，持续多次提取核心基础功能，维护独立可复现的开源版本，并形成可交付、可验证的打包和发布流程。主线开发仍由 resident_94b20c757fe7 承担；正式测试归 resident_d82c1c0b6086，宿主/工作台归 resident_f65fd96154b1，阶段汇报归 resident_0741a4fdb06d，核心规则语义归 resident_1b9016b3c6a6，必要消息治理归 resident_69a1b2227120。上层门面 resident_dfc7781a9baa，上层Steward resident_32486612a3df，所属 lineage_8794980b1bb7。
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_85192e1cc112','lineage_8794980b1bb7','投影前端团队','把 Portal 开发投影工作台当作一个独立软件来设计、实现和维护：投影协议宿主能力（含投影应用包）和三个功能区。成员自行完成职责内交互设计、实现、自检和交付，按专业可视化工具的水准实现，按理解任务验收；保留用户明确要求的独立验收及正式测试职责。负责人 resident_2546a3558662。规范：decision_7a5ae487e2e9、decision_13e1a748cf04。
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_5a4d1bfddfdd','lineage_75e3399f4877','身体记忆与局部学习 Family','研究身体与经验适应能力共同形成的方法，将身体生成规则纳入实际外层梯度或搜索，保留多种形态和动态候选。已有记忆继承、局部预测和防御机制作为起点与参照，扩展到不同身体，发现新的学习机制与科学关系；向投影提供候选和关键变化的真实回放。遵循 plan_13d78f0ae847 与 decision_66c4869fa1af 的当前版本；小网格、短程探索和共享训练资源起步。研究已启动，从现有成果继续，尊重暂停/停止且不重置一次性启动按钮。团队自主协作，不向建队者发送例行报告或常规请示。','',NULL,'',60,86400,false,'family_e31e2ffb1b3b','2026-10-15 23:37:07.039645+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_a17162f73b15','lineage_75e3399f4877','科研投影 Family','设计并发布可铺满页面的动态形态墙，同屏播放不同探索分支中的生物和真实演化过程，支持整体暂停变速、选择放大与时间浏览。动画占据主要空间，首批候选形成即接入。经历对照显示刺激的真实作用位置、范围、时刻和强度，关键反应可慢放。TAU在真实浏览器观看并操作，判断默认展示是否有意思且看得懂，修复后发布。遵循 plan_13d78f0ae847 与 decision_66c4869fa1af 的当前版本；小网格、短程探索和共享训练资源起步。研究已启动，从现有成果继续，尊重暂停/停止且不重置一次性启动按钮。团队自主协作，不向建队者发送例行报告或常规请示。','',NULL,'',60,86400,false,'family_a6402c79d126','2026-10-15 23:39:36.327245+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_81208243d431','lineage_c625a4bee56b','X bot-Family','创建并运营 Portal 自己的 X 账号；每天从 X 收集我们关心的资讯并呈现回来；以账号发布我们真实、可公开的开发进度和有趣的事情，扩大项目影响；适度与相关用户交流，并保护账号、凭据、隐私和内部资料。','',NULL,'tfi-exported-user',60,86400,false,'family_473ea36a0484','2026-10-18 23:45:40.695669+08:00'::timestamptz,'2026-10-20 02:55:57+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_256a368b5bd2','lineage_75e3399f4877','Lenia 自主科研团队','自主研究 Lenia 身体形态、行为与经验适应能力的共同演化，持续发现多种有意思的新形态和真实演化过程，同时形成新方法、新科学认识及论文。主理人 resident_afa3d4d6cf11 协调六个二级 Family，立即推进身体生成规则搜索、多样候选与环境选择；已有记忆工作按价值继续。投影提供可铺满页面的动态形态墙，首批实际候选形成即接入，逐步扩展。遵循 plan_13d78f0ae847 与 decision_66c4869fa1af 的当前版本；小网格、短程探索和共享训练资源起步。研究已启动，从现有成果继续，尊重暂停/停止且不重置一次性启动按钮。团队自主协作，不向建队者发送例行报告或常规请示。','resident_267a78bd75fa',NULL,'',60,86400,true,'family_4ed85bf56e5b','2026-10-15 23:40:54.696246+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_4215c7259082','lineage_8794980b1bb7','开发团队','Portal 开发团队按模块分派并行开发：运行与调度（Lineage/HATG/Family/Execution/Worker）交 resident_2e9ea0072551；资源、权限与存储交 resident_83d75ad3a6c7；Portal 原生界面、Chat、HATG画布与通用组件交 resident_511e229bc8c3。跨模块、集成发布和职责未明的开发交负责人 resident_6199a7a36480。模块地图、架构解释与偏离核对交 resident_60ae6d0cdf74；演化方向与改进计划交 resident_a72ae5ff152d。投影应用包、三区和宿主SDK仍归投影前端团队，测试与TAU仍归测试团队。模块开发成员可按实际任务 ForkResident 到本Family并行实现，父任务负责人划分不重叠文件边界、集成验证发布并回收临时子成员；稳定模块职责保留常驻Resident，由steward按实际工作调整。 第一条开发请求等待时即由steward评估并行：职责匹配的空闲成员优先，否则Fork对应模块成员承接独立工作；通过RelayFamilyMessage转派原请求，保留业务身份并避免重复执行。依赖或写入冲突明确说明后按序处理。
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_0e9ceb2d8a38','lineage_75e3399f4877','论文与学术讨论 Family','与科研探索同步发展科学论证、持续写作和学术讨论，维护 article_0565c33e0c03。依据 plan_13d78f0ae847 与 decision_66c4869fa1af，以 Nature Communications 的科学内容、组织、文字和图组完成度为目标，持续英文 LaTeX 写作。主笔落实每幅图由 Resident 亲自操作可见演示编辑界面绘制、编辑、排版，采用本地 LibreOffice Impress 或已有可操作 PowerPoint，保存 PowerPoint 可编辑的 PPTX，如实注明软件，不把制图绑定微软网页登录。禁止 Python 绘图或对象脚本生成整套图形/PPT 替代，允许原始仿真画面和 Blender 素材。每张完整主图及时以图件、图注和文中引用实际接入 LaTeX，编译并在 article 默认预览中看见，再逐张补齐和打磨；图注草稿或纯文字编译通过不等于完成插图。独立审稿成员实际看整页图文并协助修改；写作问题继续推动实验。与工程 Family 接通本地交互、保存导出和编译，与投影 Family 同步有图稿件及 PPTX；自主推进，无科研审批门禁，不向建队者例行汇报。','',NULL,'',60,86400,false,'family_8ed3aef9ef3a','2026-10-15 23:38:59.467958+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_a26efe27aa1e','lineage_75e3399f4877','研究工程 Family','支持可变身体规则、批量候选、外层学习和真实实验控制，复用现有仿真与计算环境。保存重放和继续探索所需的规则、初态、环境与代表性状态，为动态形态墙提供轻量回放，展示多画面不启动同等数量的训练。自主安装依赖与安排CPU/GPU，不设置科研验收流程。遵循 plan_13d78f0ae847 与 decision_66c4869fa1af 的当前版本；小网格、短程探索和共享训练资源起步。研究已启动，从现有成果继续，尊重暂停/停止且不重置一次性启动按钮。团队自主协作，不向建队者发送例行报告或常规请示。','',NULL,'',60,86400,false,'family_a4f9f6e82436','2026-10-15 23:38:07.005443+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_48f4fd95804f','lineage_75e3399f4877','文献调研与研究点拓展 Family','持续调研 Lenia、人工生命、形态与行为多样性、局部学习和演化，从文献、真实动画及跨域直觉发展不同探索分支。推动离开单一 Orbium 附近的身体规则、初态和环境探索，区分已有起点、新候选与学术新意。可自主创建并启动新研究点；常规调参留在原分支。遵循 plan_13d78f0ae847 与 decision_66c4869fa1af 的当前版本；小网格、短程探索和共享训练资源起步。研究已启动，从现有成果继续，尊重暂停/停止且不重置一次性启动按钮。团队自主协作，不向建队者发送例行报告或常规请示。','',NULL,'',60,86400,false,'family_b76d80ce0b13','2026-10-15 23:36:47.771350+08:00'::timestamptz,'2026-10-20 06:35:06+08:00'::timestamptz,'','',0);
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_f7ec6fa34b6d','lineage_8794980b1bb7','Portal 开发','作为 Portal 开发投影工作台对话区的门面，接收用户对 Portal 的理解问题、反馈和实现需求：架构与协议、演化方向、Portal 功能开发与缺陷修复交开发团队（门面 resident_94b20c757fe7）；测试、回归与 TAU 交测试团队（门面 resident_d82c1c0b6086）；工作台界面与投影协议宿主交投影前端团队（门面 resident_f65fd96154b1）；阶段汇报交汇报成员 resident_0741a4fdb06d。设计依据 decision_13e1a748cf04 与 decision_7a5ae487e2e9。
INSERT INTO "lineage"."families" ("family_id","lineage_id","title","goal","previous_leader_id","deleted_at","human_familizer_id","route_threshold","review_interval_seconds","lineage_scope","resource_id","created_at","updated_at","personal_ama_id","history_before","history_before_ordinal") VALUES ('fbi_2b2d1ecce231','lineage_8794980b1bb7','测试团队','测试成员 resident_7c2eadd4b668 负责测试目录、回归与发布门禁，并统一调度 TAU 模块验收；回归修复交回归成员，模块验收交对应 TAU Resident。测试相关请求交测试成员。
