INSERT INTO "lineage"."lineage_components" ("node_id","title","client_key","config_json","created_by_principal_id") VALUES ('effect_e2907add40eb','报告异常并交给 System 负责人','system:failures:handler', E'{"endpoints":["operator"],"failure_recipients":[],"script":"notice=$(CreateNotification title=\\"Portal 后台流程异常\\" message=\\"事件 ${event.type}，来源 ${event.subject}。详情：${event.payload}\\" severity=error)\\nsent=$(DeliverMessage resident_id=\\"${endpoint.operator}\\" message=\\"Portal 后台流程发生异常。事件：${event.type}；来源：${event.subject}；详情：${event.payload}。请检查对应运行记录和最近变更，定位原因，报告影响与处理结果。重试前核对已完成的副作用和幂等回执；不要反复盲目重跑。需要代码修改时交给 Portal 开发团队。\\")\\noutput notification_id=\\"${notice.notification_id}\\" message_id=\\"${sent.message_id}\\""}',NULL);
