INSERT INTO "lineage"."lineage_components" ("node_id","title","client_key","config_json","created_by_principal_id") VALUES ('effect_1d20824f7d69','检查本轮摘要',NULL, E'{"endpoints":[],"failure_recipients":["tfi-exported-user"],"script":"checked=$(CheckResidentWorkSummary resident_id=\\"${event.subject_resident_id}\\" message_id=\\"${event.payload.message_id}\\")\\nif [ \\"${checked.consolidation_due}\\" != \\"true\\" ]; then\\n  output status=\\"${checked.status}\\"\\n  exit\\nfi\\nstate=$(ListResidentStates resident_ids:=[${arguments.steward}] include_viewer_state:=false)\\nif [ \\"${state.states.0.state.work_state}\\" != \\"idle\\" ]; then\\n  output status=\\"busy\\"\\n  exit\\nfi\\nif [ \\"${state.states.0.state.queued_count}\\" -gt 0 ]; then\\n  output status=\\"busy\\"\\n  exit\\nfi\\ninputs=$(GetFamilySummaryInputs resident_id=\\"${arguments.facade}\\" overview_only:=true)\\nif [ \\"${inputs.needs_update}\\" != \\"true\\" ]; then\\n  output status=\\"unchanged\\"\\n  exit\\nfi\\nsent=$(DispatchFamilyTask resident_id=\\"${arguments.facade}\\" trigger=\\"summary\\" message_id=\\"${inputs.notification.message_id}\\")\\noutput status=\\"requested\\" message_id=\\"${sent.message_id}\\""}','resident_e8b66d1ae69d');
