INSERT INTO "lineage"."lineage_components" ("node_id","title","client_key","config_json","created_by_principal_id") VALUES ('effect_2a726934c07d','按需归纳工作摘要',NULL, E'{"endpoints":[],"failure_recipients":["tfi-exported-user"],"script":"state=$(ListResidentStates resident_ids:=[${arguments.steward}] include_viewer_state:=false)\\nif [ \\"${state.states.0.state.work_state}\\" != \\"idle\\" ]; then\\n  output status=\\"busy\\"\\n  exit\\nfi\\nif [ \\"${state.states.0.state.queued_count}\\" -gt 0 ]; then\\n  output status=\\"busy\\"\\n  exit\\nfi\\ninputs=$(GetFamilySummaryInputs resident_id=\\"${arguments.facade}\\" overview_only:=true)\\nif [ \\"${inputs.needs_update}\\" != \\"true\\" ]; then\\n  output status=\\"unchanged\\"\\n  exit\\nfi\\nsent=$(DispatchFamilyTask resident_id=\\"${arguments.facade}\\" trigger=\\"summary\\" message_id=\\"${inputs.notification.message_id}\\")\\noutput status=\\"requested\\" message_id=\\"${sent.message_id}\\""}','resident_e8b66d1ae69d');
INSERT INTO "lineage"."lineage_components" ("node_id","title","client_key","config_json","created_by_principal_id") VALUES ('effect_4365f3ed2a74','有待写摘要才交给承担者',NULL, E'{"endpoints":["writer"],"script":"# 有可认领的摘要、且承担者空闲时，清空它的上下文再把这一轮交给它；否则跳过，不产生模型调用。\\n# business_ref 标出这是职责本身的运行，发现模块不把它算作承担者要被摘要的工作。\\nqueue=$(GetResidentSummaryQueue)\\nif [ \\"${queue.ready}\\" -eq 0 ]; then\\n  output delivered=\\"false\\" reason=\\"没有可认领的摘要\\" waiting=\\"${queue.waiting}\\"\\n  exit\\nfi\\nst=$(ListResidentStates resident_ids:=[${endpoint.writer}] include_viewer_state:=false)\\nif [ \\"${st.states.0.state.work_state}\\" != \\"idle\\" ] || [ \\"${st.states.0.state.queued_count}\\" -ne 0 ]; then\\n  output delivered=\\"false\\" reason=\\"承担者正忙\\" ready=\\"${queue.ready}\\"\\n  exit\\nfi\\nif ClearContext resident_id=\\"${endpoint.writer}\\"; then\\n  sent=$(DeliverMessage resident_id=\\"${endpoint.writer}\\" \\\\\\n    message=\\"读 ${share_root}/Agents/lineage_ed619225d417/residents/resident_fbaf22f40dc6/workspace/duties/resident-summary.md，按其中步骤亲自完成本轮 Resident 发现摘要，并汇报。\\" \\\\\\n    business_ref=\\"duty/resident-summary\\")\\n  output delivered=\\"true\\" ready=\\"${queue.ready}\\" message_id=\\"${sent.message_id}\\"\\nelse\\n  output delivered=\\"false\\" reason=\\"清空上下文被拒绝\\" ready=\\"${queue.ready}\\"\\nfi"}',NULL);
