INSERT INTO "lineage"."lineage_components" ("node_id","title","client_key","config_json","created_by_principal_id") VALUES ('effect_639dcc0864d6','启动研究 · 初始化与首次分派',NULL, E'{"endpoints":["coordinator","literature","learning","evolution","engineering","paper","projection"],"failure_recipients":[],"script":"UpdateSharedState lineage_id=lineage_75e3399f4877 key=research.started value:=true\\nUpdateSharedState lineage_id=lineage_75e3399f4877 key=research.desired_state value:=\\"running\\"\\nDeliverMessage resident_id=\\"${endpoint.coordinator}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《统筹科研探索》。\\"}]}\\nDeliverMessage resident_id=\\"${endpoint.literature}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《启动本组研究》。\\"}]}\\nDeliverMessage resident_id=\\"${endpoint.learning}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《启动本组研究》。\\"}]}\\nDeliverMessage resident_id=\\"${endpoint.evolution}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《启动本组研究》。\\"}]}\\nDeliverMessage resident_id=\\"${endpoint.engineering}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《启动本组研究》。\\"}]}\\nDeliverMessage resident_id=\\"${endpoint.paper}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《启动本组研究》。\\"}]}\\nDeliverMessage resident_id=\\"${endpoint.projection}\\" activation_policy=\\"enqueue_and_trigger\\" message:={\\"role\\":\\"user\\",\\"content_parts\\":[{\\"type\\":\\"text\\",\\"text\\":\\"执行具名工作项《启动本组研究》。\\"}]}"}',NULL);
INSERT INTO "lineage"."lineage_components" ("node_id","title","client_key","config_json","created_by_principal_id") VALUES ('effect_cbfa930bab12','转交所选成员',NULL, E'{"endpoints":[],"failure_recipients":["tfi-exported-user"],"script":"ref=\\"${event.payload.input_business_ref}\\"\\nif [ \\"${ref:0:13}\\" != \\"family-route/\\" ]; then\\n  fail \\"Router 输入缺少 Family 请求引用\\"\\nfi\\nif [ \\"${ref:34:9}\\" != \\"/message/\\" ]; then\\n  fail \\"Router 输入的 Family 请求引用无效\\"\\nfi\\nfacade=\\"${ref:13:21}\\"\\nmid=\\"${ref:43}\\"\\ntarget=\\"${packet.message.data.target}\\"\\nif [ -z \\"$target\\" ]; then\\n  DispatchFamilyTask resident_id=\\"$facade\\" trigger=\\"route_review\\" source_message_id=\\"$mid\\" facts:={\\"reason\\":\\"Router 缺少 target\\"}\\n  fail \\"Family Router 输出格式或字段无效：缺少 message.data.target\\"\\nfi\\nchosen=\\"\\"\\nif [ \\"$target\\" = \\"${arguments.steward}\\" ]; then\\n  chosen=\\"$target\\"\\nfi\\nfor member in ${arguments.members}; do\\n  if [ \\"$member\\" = \\"$target\\" ]; then\\n    chosen=\\"$member\\"\\n  fi\\ndone\\nif [ -z \\"$chosen\\" ]; then\\n  DispatchFamilyTask resident_id=\\"$facade\\" trigger=\\"route_review\\" source_message_id=\\"$mid\\" facts:={\\"reason\\":\\"成员已不在名册\\"}\\n  fail \\"Family Router 选择的成员不在当前名册中\\"\\nfi\\nif [ \\"${packet.message.data.scope}\\" = \\"out\\" ]; then\\n  # No member''s duties cover it: the steward decides whether a new member takes it.\\n  gap=\\"${packet.message.data.gap}\\"\\n  if [ -z \\"$gap\\" ]; then\\n    gap=\\"Router 未写明\\"\\n  fi\\n  held=$(RelayFamilyMessage resident_id=\\"$facade\\" message_id=\\"$mid\\" member_id=\\"$chosen\\" scope_gap=\\"$gap\\" reason=\\"${packet.message.text}\\")\\n  output target=\\"$chosen\\" state=\\"${held.status}\\" scope=\\"out\\" gap=\\"$gap\\" reason=\\"${packet.message.text}\\"\\n  exit\\nfi\\nrelayed=$(RelayFamilyMessage resident_id=\\"$facade\\" message_id=\\"$mid\\" member_id=\\"$chosen\\")\\nif [ \\"${relayed.status}\\" = \\"withdrawn\\" ]; then\\n  # Stopped while the Router was choosing: nobody gets it, and there is nothing to review.\\n  output target=\\"$chosen\\" state=\\"withdrawn\\"\\n  exit\\nfi\\nconfidence=\\"${packet.message.data.confidence}\\"\\nif [ -z \\"$confidence\\" ]; then\\n  confidence=\\"0\\"\\nfi\\nif [ \\"$confidence\\" -lt \\"${arguments.threshold}\\" ]; then\\n  DispatchFamilyTask resident_id=\\"$facade\\" trigger=\\"route_review\\" source_message_id=\\"$mid\\" facts:=${packet.message.data}\\nfi\\noutput target=\\"$chosen\\" confidence=\\"$confidence\\" reason=\\"${packet.message.text}\\""}',NULL);
