INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_3cc43a13e3c5','lineage_8794980b1bb7','route','event_source_164d88e11beb','output','effect_48bfde2f070f','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"family_id":{"value":"fbi_2b2d1ecce231"},"family_tasks":{"value":{"organization":{"guide":"根据变化按需读取当前 Family、成员职责和原消息。仅处理与分工、运行、恢复有关的工作；按相关性定向通知，不广播全部材料。初始化时检查分工，随后保持可用等待事件。","prompt":"处理当前组织变化或背景更新。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"初始化、名册变更或背景更新"},"quota":{"guide":"按需查看成员与后端额度，判断任务强度及可用账号；必要时 RestartSession 迁移并保留上下文，完成后 RelayFamilyMessage(quota_reviewed=true, reason=理由) 继续原请求。Router 和 Steward 自身的可用性由运行时保障；无可用后端时通知实际创建人。","prompt":"评估额度受限成员，安排原请求继续执行。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"业务成员额度不足"},"recovery":{"guide":"用 CheckFamilyRecovery 查看原故障及状态，按需读 GetInputState、GetTriggerPath、ListResidentStates，恢复原任务并核验结果。不要把修复回执当原任务成功。成员关闭接单导致原任务阻塞时，查明原因并用 OpenIntake(open=true) 恢复接单，继续原输入；排队中的输入不用重复投递。必要时 RestartSession 并核验操作结果；常规恢复无效时定位修复缺陷，或以 escalate_reason 说明具体阻塞并求助实际创建人。保留取消、删除和明确停止的任务；关闭整个 Family 门面表示暂停自维护，单个成员关闭不再自动免除恢复职责。","prompt":"核验并处理当前未解决故障。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"工作失败或接单阻塞"}}},"lineage_id":{"value":"lineage_8794980b1bb7"}}}},"unavailable_policy":"drop"}',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_283742377cef','lineage_8794980b1bb7','route','filter_58d2e0c98416','output','resident_60ae6d0cdf74','invoke',NULL,NULL,'{"expires_after_seconds":0,"invoke_profiles":{"agent":{"arguments":{"prompt":{"value":"Portal 架构自动核对完成，有偏离或脚本失败。事件包含 script_run_id、输出汇总与状态。先用 GetScriptRun 与 ReadScriptRunOutput 读取 architecture-audit.json；结合对应发布 commit 判断修改模块地图、实现位置还是 Design。若需修改规范规则，联系 resident_e8b66d1ae69d。"}}}},"queue_limit":10,"unavailable_policy":"queue"}',NULL,NULL,NULL,NULL,NULL);
