INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_1caf10922c51','lineage_75e3399f4877','route','event_source_24e1654cd251','output','resident_d3ccfa2d95b7','invoke','执行具名工作项《用伴随权重检验复制约定》',NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"agent":{"arguments":{"prompt":{"value":"执行具名工作项《用伴随权重检验复制约定》。先读本Lineage research.desired_state/started，暂停或未开始时不启动计算。接续你已有供体核尺度/保留组织交换敏感性问题，勿重做前后交叉矩阵。主理人的固定身体伴随诊断已完成：src/analysis/memory_influence.py、runs/jobs/8fb3c383-7074-4fd4-979d-e496c62f9825/{results.json,influence_fields.npz}，源身体fdca0647-a21f-4e08-8ef4-dc973a6d6fb5/growth_1_trained.npz；四相位同体无刺激360步，beta=1约1.84%–2.00%初始质量承载90%贡献，等10%质量最高权重写入最终约1，低权重约0，均匀弱写入.1，独立inherit前向误差2.22e-15。\\n请实现并实跑一项有限CPU敏感性实验，采用你决定的少量明确供体核尺度和保留组织状态交换强度，保留原参数精确基线。说明交换的具体局部算子及是否守恒密度加权记忆；不要默认局部平均即守恒交换。复用四相位固定身体路径，各算子各自计算伴随，不能把原3x3权重沿用到改变的算子；核不对称时用转置核。记录总权重、归一化贡献集中度、前部贡献及各相位；仅归一化会隐藏信号整体衰减，故总权重必留。对新算子做独立前向/伴随一致性检查。\\n等初始密度加权写入量同时保留两类比较：按每个算子权重选择的高/低贡献位置；固定使用原算子高/低权重位置及相同几何前后位置，以辨认信息入口是否迁移而非重选位置掩盖变化。可复用原10%预算和分数边界。根据有限结果选择是否需要一个局部真实经历续接，勿增加全反转矩阵或宽扫描。通过runtime/runner.py提交，无GPU；报告预期与实际未来平均记忆、每种算子参数、来源/产物路径及解释边界。固定轨迹权重是事后机制诊断，不是在线策略或身体收益。完成后将结果交我和主理人，摘要/shared state标明实际完成，便于本组收束。已有相关计算则直接接续并补齐缺项，不另起重复作业。"}}}},"max_messages":1,"queue_limit":1,"unavailable_policy":"queue"}',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_e192aa8f2b9c','lineage_ed619225d417','route','event_source_6a15828b7c22','output','resident_e267c94e7252','invoke',NULL,NULL,'{"expires_after_seconds":0,"invoke_profiles":{"agent":{"arguments":{"prompt":{"value":"写昨天的 Pulse 日报。读 ${share_root}/Agents/lineage_ed619225d417/residents/resident_e267c94e7252/workspace/duties/pulse.md，按其中「日报（daily）」的步骤亲自读材料、写汇总并发布（缺省日期即刚结束的一期），最后在 runs.md 记一行，并在回复中给出 global_summary。"}}}},"queue_limit":10,"unavailable_policy":"queue"}',NULL,NULL,NULL,NULL,NULL);
