L,NULL);
INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_87da1b3cf8ed','lineage_8794980b1bb7','route','event_source_9df126016aa6','output','effect_487ac9ada5cd','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"facade":{"value":"resident_dfc7781a9baa"},"family_tasks":{"value":{"review":{"guide":"按需查看成员职责、近期活动和队列，判断组织是否需要调整。闲置或重叠是判断依据，不是自动删除指令。保留仍有效的任务与承诺；涉及交接时先完成交接。重要组织结论保存到 Family 或项目记录，需要人决定的事项向 Family 实际创建人汇报。","prompt":"回顾当前分工，处理有依据的组织问题。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"周期组织回顾"}}},"trigger":{"value":"review"}}}},"unavailable_policy":"latest"}',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_8e8a823e58c1','lineage_8794980b1bb7','route','event_source_3b6497631e7c','output','effect_2a726934c07d','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"facade":{"value":"resident_dfc7781a9baa"},"family_tasks":{"value":{"summary":{"guide":"用 GetFamilySummaryInputs(resident_id=facade, overview_only=true) 找到待归纳成员，再按需读取GetResidentSummaries(include_maintenance=true)。仅业务成员记录近期事实；Router 和 Steward 不维护自身摘要。Steward 归纳业务成员阶段与长期层；用 UpdateResidentWorkSummary 的 consolidation 和 expected_revision 提交，覆盖已归纳片段。所有层与字段共用总字数预算；保留未完成承诺、阻塞、重要约束及来源。项目长记录独立保存，摘要只留当前结论与入口。达到预算时重写取舍，不按时间删除未解决事项。归纳后重读 GetFamilySummaryInputs；facade_needs_update 为真时，用返回的 expected_revision、source_versions 和九字段 summary 调用 UpdateResidentWorkSummary 更新门面。版本冲突后重读重算；材料未变不写入，不按输入批次另发简报，不群发。","prompt":"按需归纳业务成员摘要并更新 Family 门面，在总预算内保留有效认知。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"摘要达到时间或工作量阈值"}}},"steward":{"value":"resident_32486612a3df"}}}},"unavailable_policy":"drop"}',NULL,NULL,NULL,NULL,NULL);
