INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_b7bb900d62a7','lineage_c625a4bee56b','route','event_source_efba6cf88543','output','effect_a1666abe0727','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"facade":{"value":"resident_dc9544f62caf"},"family_tasks":{"value":{"review":{"guide":"按需查看成员职责、近期活动和队列，判断组织是否需要调整。闲置或重叠是判断依据，不是自动删除指令。保留仍有效的任务与承诺；涉及交接时先完成交接。重要组织结论保存到 Family 或项目记录，需要人决定的事项向 Family 实际创建人汇报。","prompt":"回顾当前分工，处理有依据的组织问题。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"周期组织回顾"}}},"trigger":{"value":"review"}}}},"unavailable_policy":"latest"}',NULL,NULL,NULL,NULL,NULL);
