INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_f2f75436712d','lineage_8794980b1bb7','route','resident_806c81a25de6','output','effect_6857683086cb','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"family_tasks":{"value":{"recruit":{"guide":"读取原请求和候选职责，决定招募、调整分工或由最接近的成员承担。需要招募时 CreateResident并用 UpdateFamily 加入名册，再 RelayFamilyMessage(scope_reviewed=true, reason=判断依据)交回原请求。不要另造一条业务请求；原发送者的取消必须生效。","prompt":"处理职责缺口，安排原请求的承接者。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"Router 发现职责缺口"},"route_review":{"guide":"读取原请求、Router 输出与当前名册。低置信度已转交的请求不重复派发；必要时用RelayFamilyMessage(reassign=true, reason=理由) 改派。格式错误未转交时修复原路由。组织成果若已在本复核输入完成，不再执行创建；本轮完成并有真实回复后，由授权恢复者用 ResolveFamilyRequest 将既有成果归档到原失败请求，再 CheckFamilyRecovery 核验。","prompt":"复核原请求的路由，必要时纠正。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"路由需要复核"}}},"members":{"value":["resident_2e9ea0072551","resident_511e229bc8c3","resident_60ae6d0cdf74","resident_6199a7a36480","resident_71c89420667f","resident_786fa6244bb1","resident_83d75ad3a6c7","resident_a72ae5ff152d","resident_c98445c0d63f"]},"prompt":{"value":""},"steward":{"value":"resident_6b4867560621"},"threshold":{"value":60}}}},"parallel":true,"unavailable_policy":"drop"}',NULL,NULL,NULL,NULL,NULL);
