INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_a35eebc6e135','lineage_75e3399f4877','route','event_source_a83f04ee6bc0','output','effect_d58f9bc1d81d','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"facade":{"value":"resident_6b38cf2de6bc"},"family_tasks":{"value":{"queue":{"guide":"先用 GetMailbox 和 ListResidentStates 核对触发成员当前待办、运行任务和实际积压，事件指标只代表触发时。先整理再评估扩容：有整理权限时，用 MergeMailboxItems 合并适合一轮处理的相关等待请求，必要时 ReorderMailbox 调整顺序；保留原文、作者、独立诉求、依赖和取消语义，不动已领取输入。合并只减少轮次，不压缩原文或消除实际工作量；info 不参与合并，不为降低队列数字取消有效请求。整理后重读 mailbox，结合 GetResidentSummaries 判断剩余任务是否独立、现有成员能否分担；确需新增能力或并行容量时才 CreateResident 并用 UpdateFamily 加入。门面原请求用 RelayFamilyMessage(reassign=true, reason=理由) 改派，其他输入先明确交接，避免重复执行。若反复出现同一发送者的无行动价值消息，可基于具体例子定向提醒对方：日常进展写摘要，仅为必要信息、重要运行影响或约定工作流发消息；无新情况不重复提醒、不群发或要求逐条确认。重要决定及依据保存到 Family 或项目记录；需要相关成员行动时才通知。保留串行时说明原因；仍有积压时安排必要复查。","prompt":"先整理当前 mailbox，再判断剩余任务是否需要分流或增员。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"成员队列积压"}}},"trigger":{"value":"queue"}}}},"unavailable_policy":"latest"}',NULL,NULL,NULL,NULL,NULL);
