INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_cbd3f283ed0e','lineage_8794980b1bb7','route','event_source_870fb5c0a708','output','effect_0cfce1e2ebc7','invoke',NULL,NULL, E'{"expires_after_seconds":0,"invoke_profiles":{"effect":{"arguments":{"facade":{"value":"resident_f65fd96154b1"},"family_tasks":{"value":{"summary":{"guide":"用 GetFamilySummaryInputs(resident_id=facade, overview_only=true) 找到待归纳成员，再按需读取GetResidentSummaries(include_maintenance=true)。仅业务成员记录近期事实；Router 和 Steward 不维护自身摘要。Steward 归纳业务成员阶段与长期层；用 UpdateResidentWorkSummary 的 consolidation 和 expected_revision 提交，覆盖已归纳片段。所有层与字段共用总字数预算；保留未完成承诺、阻塞、重要约束及来源。项目长记录独立保存，摘要只留当前结论与入口。达到预算时重写取舍，不按时间删除未解决事项。归纳后重读 GetFamilySummaryInputs；facade_needs_update 为真时，用返回的 expected_revision、source_versions 和九字段 summary 调用 UpdateResidentWorkSummary 更新门面。版本冲突后重读重算；材料未变不写入，不按输入批次另发简报，不群发。","prompt":"按需归纳业务成员摘要并更新 Family 门面，在总预算内保留有效认知。\\n${facts}\\n指南：${guide_path}（${guide_version}）","role":"steward","title":"摘要达到时间或工作量阈值"}}},"steward":{"value":"resident_2eecc2e71244"}}}},"unavailable_policy":"drop"}',NULL,NULL,NULL,NULL,NULL);
