INSERT INTO "lineage"."lineage_edges" ("edge_id","lineage_id","edge_type","source_node_id","source_port","target_node_id","target_port","label","client_key","config_json","revision_request_id","explanation","operation_contract_json","note","deleted_at") VALUES ('wire_78e57421b84a','lineage_75e3399f4877','route','event_source_a8f6472ffafe','output','resident_afa3d4d6cf11','invoke','收敛主线结果与有限收尾；禁止扩展','research-followthrough-to-pi-v1','{"expires_after_seconds":0,"invoke_profiles":{"agent":{"arguments":{"prompt":{"value":"执行已收敛研究的实质结果整合。先读 research.started、research.desired_state 及 research.progress.convergence。用户已于2026-10-20要求不要再扩展，覆盖任何旧的多方向/每批续接授权。唯一范围见 ${share_root}/Projects/元胞自动机研究/knowledge_base/research/experience_learning/research_convergence_20261020.json：现有 scalar-only 同一身体的经验依赖行为、内容干预和强简单规则比较；d3至多一次固定协议有限核验，其他研究方向只收尾归档。按owner+task+SHA及实际输入去重，已处理/确认/纯排版不产生任务。未启动、暂停、停止时不分派科研。核最小新证据，更新共享并在确需主笔或投影整合实质变化时只向直接负责人发一次请求。正负结果均用于收束结论，不因失败、目标未达成、工作结束或requires_pi_choice再开新模型/宿主/任务/批次。旧事件不能恢复扩展。具名真实外部阻塞只解决对应收尾工作。route_validation只记录送达。禁止定时、自唤醒、重复确认或恢复已关闭的work_finished事件源。"}}}},"unavailable_policy":"latest"}',NULL,NULL,NULL,NULL,NULL);
