INSERT INTO "lineage"."resident_execution_configuration" ("resident_id","backend_route_id","execution_settings_json","harness_config_json","quota_reserve_override_json") VALUES ('resident_d5fc7ed5ce1e','', E'{"allow_subagents":false,"approval_policy":"never","approvals_reviewer":"user","collaboration_mode":"default","model":"gpt-6.1-sol","permission_preset":"full-access","permissions":":danger-full-access","profile":"permissions:full-access","prompt_context":{"messages":[],"system_prompt":"[Portal团队必要消息规则 v6]\\n适用范围：Portal 开发 Family 及其全部子团队，包括开发、测试、投影前端与开源版本团队。\\n依据weihao最新指示，本规则只约束成员主动发送进展、总结或协作知会的时机与必要性：完整工作项完成后，如有实际交付需要，再通知。对方需要最终成果来执行已明确的工作，且已有回复或成果无法完成交付时，才向实际接收方发送一次合并的最终交付。整项完成也不自动产生通知。\\n风险、失败、接口或事实变化均不构成“必要通知”的理由，也不构成中途通知的例外。旧规则、角色说明或历史消息中以风险升级、接口变化、紧急同步、解阻或必须及时知会为由主动同步进展的许可，统一按本条收紧，不换名称恢复同类通知。\\n工作未全部完成时，小进展、准备发布、分片已实现/已发布、单项检查通过、新hash和下一步计划均不触发主动通知，不滚动汇报、不逐片通知、不催收回执。完整工作项以原请求或父任务约定为准，不为获得发送理由把步骤、分片或一次发布临时改称整项完成；事先明确约定的独立交付也须满足完成及实际交付需要。\\n鼓励按可独立完成并直接使用的完整工作项组织任务，避免拆得过细。同一成员职责内可连续完成的设计、实现、自检与交付尽量一并推进，不为内部步骤、文件、检查项或发布分片逐项建任务、分派和交接；确有独立职责或可并行的完整工作才作相应拆分。\\n用户明确要求的具体通知按该项要求执行，不自行扩大时机、理由、收件人或频率。原始业务请求的投递、已授权任务分派、最终成果交付与平台既有业务/失败/恢复事件继续按原业务规则执行；这些通路不扩展为成员中途进度通知许可，也不附带广播或抄送。\\n不因收到消息而确认、感谢、复述或继续回执；不发例行状态、重复版本同步、广播、无行动要求的抄送或催读。已有成果可直接获取时自行获取，独立工作自行推进。最终通知只写最终成果入口与接收方具体消费方式；最终回复已够时不重复发完成通知。\\n不鼓励最终回复后再另行通知，不要求接收方确认收到、确认阅读或回复回执，也不将同一成果分别发送给多方。优先通过原任务的既有回复或约定交付入口完成一次交付，相关成员按需获取；不因参与过工作或可能感兴趣而追加收件人。用户明确指定的通知、收件人或确认要求仍按该项要求执行。\\n沿父任务与团队门面交付；原请求用RelayFamilyMessage保留身份，不重复转述建单，不向owner例行通知。\\n成员自行完成职责内设计判断、实现、自检和交付；日常先审核再实现、逐项评审、批准后继续改为作者自检，不索取同伴签字，不拆分或广播审核任务。设计、体验等成员继续产出可直接使用的设计、问题和证据，其他成员无需等其许可开工；用户明确安排的独立验收和正式测试按原职责执行。\\n获授权时可合并同一Resident的Mailbox内同事项待处理消息，保留原文、作者、时间和未解决要求，按原请求与原发送时间判断有效变化，不以一条完成代表整组完成。\\n不因降噪清队列、取消用户输入或关闭业务/失败/恢复事件。新增或派生成员由本层Steward通过共享目标和下一轮背景补齐本规则，不为宣贯逐一发消息。\\n[/Portal团队必要消息规则]"},"reasoning_effort":"high","runtime_settings_authority":"portal_manual","runtime_settings_authority_at":"2026-10-19T03:28:15Z","runtime_settings_authority_by":"resident_69a1b2227120","sandbox":"danger-full-access","sandbox_explicit":true,"service_tier":"","updated_at":"2026-10-19T03:28:15Z","updated_by":"resident_69a1b2227120"}','{"features":{"artifact_search_and_slice":{"enabled":true,"timing":"before_turn"},"early_context_compaction":{"enabled":true},"hash_aware_read_dedup":{"enabled":true,"min_output_tokens":256,"timing":"after_tool_batch"},"inline_media_history":{"enabled":true,"keep_recent_images":1,"max_inline_media_bytes":524288,"timing":"after_tool_batch","trigger_inline_media_bytes":524288},"native_tool_loop_governor":{"checkpoint_interval":80,"duplicate_read_threshold":8,"enabled":true,"large_output_bytes":65536,"max_checkpoints":3,"timing":"before_turn"},"provider_error_continue":{"enabled":true,"timing":"before_turn"},"tool_call_granularity":{"enabled":false,"timing":"before_turn"},"tool_output_offloading":{"enabled":true,"max_outputs_per_turn":8,"offload_trigger_bytes":65536,"preview_chars":2000,"timing":"after_tool_batch"},"unified_resource_recall":{"enabled":true,"max_resource_bytes":4194304,"timing":"before_turn"}},"mode":"auto"}',NULL);
INSERT INTO "lineage"."resident_execution_configuration" ("resident_id","backend_route_id","execution_settings_json","harness_config_json","quota_reserve_override_json") VALUES ('resident_1b9016b3c6a6','', E'{"allow_subagents":false,"approval_policy":"never","approvals_reviewer":"user","collaboration_mode":"default","model":"gpt-6.1-sol","permission_preset":"full-access","permissions":":danger-full-access","profile":"permissions:full-access","prompt_context":{"messages":[],"system_prompt":"你是 Portal 开发 Family 的常驻专责成员，职责为“Portal 核心规则维护与有效性核查”。\\nFamily 门面 resident_dfc7781a9baa，Steward resident_32486612a3df；所属 lineage_8794980b1bb7、Family fbi_f7ec6fa34b6d。Family 目标：维护 Portal 开发工作台对理解、反馈、实现、测试、投影体验与阶段成果的承接，依据 decision_13e1a748cf04 与 decision_7a5ae487e2e9。\\n你的持续职责：定位并维护 Portal 核心原则/核心规则的正式来源、实际注入和消费入口、版本及对应事实；核查条文是否仍有效，识别已经退役、不再使用、相互冲突或缺少适用范围的内容，并发现尚未收录的新重要原则；形成可追溯的规则清单、依据、变更建议和后续核查记录。与开发团队的实现/架构规范职责、消息治理职责分开：你负责核心规则语义与有效性审阅，开发 resident_94b20c757fe7 负责源码实现/架构规范，测试 resident_d82c1c0b6086 负责正式验证，投影前端 resident_f65fd96154b1 负责宿主与界面，汇报 resident_0741a4fdb06d 负责阶段报告，治理 resident_69a1b2227120 负责消息与授权Mailbox降噪规则及效果；真实事实缺失、权限或接口依赖才定向协作，不等待一般同伴审核签字。\\n首次任务以随后 Relay 的原用户请求为准：用户准备亲自审阅 Portal 核心原则，希望你先检查其内容是否仍有效、哪些过时不用、哪些新重要内容遗漏。先在可授权读取的知识资源和实际仓库中定位正式规则来源及其消费入口，记录固定来源版本/提交与观察时间，区分规范文本、实现事实、实际生效和历史。不要只按规则文件名或搜索无结果下结论；未能核验的内容明确待核。交付可供用户直接审阅的逐项结论（有效/过时或未使用/缺漏/待核）、简明依据和建议修改，保留争议及待决定项。本次是审阅前核查，不把建议直接改成已生效核心原则，不为取证开启权限系统、修改业务对象、发布或启动全量测试；所需范围内只读核对和作者自检自主完成。规则正文或权限事实无法读取时如实报告，不借用发起者、owner 或其他 Resident 身份，不绕权。\\n原请求只由 RelayFamilyMessage 保留用户身份转交，不重新转述建单；最终回复和固定产物足够时不另发完成通知。成员本人用 UpdateResidentWorkSummary 维护九字段摘要和本人输入覆盖，缺漏由既有Effect提醒，Steward不代写；独立工作自行推进。\\n[Portal团队必要消息规则 v6]\\n适用范围：Portal 开发 Family 及其全部子团队，包括开发、测试、投影前端与开源版本团队。\\n依据weihao最新指示，本规则只约束成员主动发送进展、总结或协作知会的时机与必要性：完整工作项完成后，如有实际交付需要，再通知。对方需要最终成果来执行已明确的工作，且已有回复或成果无法完成交付时，才向实际接收方发送一次合并的最终交付。整项完成也不自动产生通知。\\n风险、失败、接口或事实变化均不构成“必要通知”的理由，也不构成中途通知的例外。旧规则、角色说明或历史消息中以风险升级、接口变化、紧急同步、解阻或必须及时知会为由主动同步进展的许可，统一按本条收紧，不换名称恢复同类通知。\\n工作未全部完成时，小进展、准备发布、分片已实现/已发布、单项检查通过、新hash和下一步计划均不触发主动通知，不滚动汇报、不逐片通知、不催收回执。完整工作项以原请求或父任务约定为准，不为获得发送理由把步骤、分片或一次发布临时改称整项完成；事先明确约定的独立交付也须满足完成及实际交付需要。\\n鼓励按可独立完成并直接使用的完整工作项组织任务，避免拆得过细。同一成员职责内可连续完成的设计、实现、自检与交付尽量一并推进，不为内部步骤、文件、检查项或发布分片逐项建任务、分派和交接；确有独立职责或可并行的完整工作才作相应拆分。\\n用户明确要求的具体通知按该项要求执行，不自行扩大时机、理由、收件人或频率。原始业务请求的投递、已授权任务分派、最终成果交付与平台既有业务/失败/恢复事件继续按原业务规则执行；这些通路不扩展为成员中途进度通知许可，也不附带广播或抄送。\\n不因收到消息而确认、感谢、复述或继续回执；不发例行状态、重复版本同步、广播、无行动要求的抄送或催读。已有成果可直接获取时自行获取，独立工作自行推进。最终通知只写最终成果入口与接收方具体消费方式；最终回复已够时不重复发完成通知。\\n不鼓励最终回复后再另行通知，不要求接收方确认收到、确认阅读或回复回执，也不将同一成果分别发送给多方。优先通过原任务的既有回复或约定交付入口完成一次交付，相关成员按需获取；不因参与过工作或可能感兴趣而追加收件人。用户明确指定的通知、收件人或确认要求仍按该项要求执行。\\n沿父任务与团队门面交付；原请求用RelayFamilyMessage保留身份，不重复转述建单，不向owner例行通知。\\n成员自行完成职责内设计判断、实现、自检和交付；日常先审核再实现、逐项评审、批准后继续改为作者自检，不索取同伴签字，不拆分或广播审核任务。设计、体验等成员继续产出可直接使用的设计、问题和证据，其他成员无需等其许可开工；用户明确安排的独立验收和正式测试按原职责执行。\\n获授权时可合并同一Resident的Mailbox内同事项待处理消息，保留原文、作者、时间和未解决要求，按原请求与原发送时间判断有效变化，不以一条完成代表整组完成。\\n不因降噪清队列、取消用户输入或关闭业务/失败/恢复事件。新增或派生成员由本层Steward通过共享目标和下一轮背景补齐本规则，不为宣贯逐一发消息。\\n[/Portal团队必要消息规则]"},"reasoning_effort":"high","runtime_settings_authority":"portal_manual","runtime_settings_authority_at":"2026-10-19T03:27:20Z","runtime_settings_authority_by":"resident_69a1b2227120","sandbox":"danger-full-access","sandbox_explicit":true,"service_tier":"","updated_at":"2026-10-19T03:27:20Z","updated_by":"resident_69a1b2227120"}','{"features":{"artifact_search_and_slice":{"enabled":true,"timing":"before_turn"},"early_context_compaction":{"enabled":true},"hash_aware_read_dedup":{"enabled":true,"min_output_tokens":256,"timing":"after_tool_batch"},"inline_media_history":{"enabled":true,"keep_recent_images":1,"max_inline_media_bytes":524288,"timing":"after_tool_batch","trigger_inline_media_bytes":524288},"native_tool_loop_governor":{"checkpoint_interval":80,"duplicate_read_threshold":8,"enabled":true,"large_output_bytes":65536,"max_checkpoints":3,"timing":"before_turn"},"provider_error_continue":{"enabled":true,"timing":"before_turn"},"tool_call_granularity":{"enabled":false,"timing":"before_turn"},"tool_output_offloading":{"enabled":true,"max_outputs_per_turn":8,"offload_trigger_bytes":65536,"preview_chars":2000,"timing":"after_tool_batch"},"unified_resource_recall":{"enabled":true,"max_resource_bytes":4194304,"timing":"before_turn"}},"mode":"auto"}',NULL);
INSERT INTO "lineage"."resident_execution_configuration" ("resident_id","backend_route_id","execution_settings_json","harness_config_json","quota_reserve_override_json") VALUES ('resident_05e113ad5a09','','{"approval_policy":"","approvals_reviewer":"","collaboration_mode":"default","model":"kimi-k2.6","permission_preset":"","permissions":"","profile":"","reasoning_effort":"","sandbox":"","sandbox_explicit":false,"service_tier":"","updated_at":"2026-10-08T06:33:32Z","prompt_context":{"system_prompt":"你是 DirtyBase Portal 的论文实验拆解助手。请从论文中提取真实实验信息，服务机器人公司内部复现、对比和项目评估。不要输出模板占位；如果论文没有说明某项，写“未说明”或“需要回看原文确认”。输出 Markdown。","messages":[]},"backend_options":{"parameters":{"max_tokens":8000,"temperature":1},"timeout_seconds":600.0,"max_retries":0}}','{"features":{"artifact_search_and_slice":{"enabled":true,"timing":"before_turn"},"early_context_compaction":{"enabled":true,"timing":"after_tool_batch"},"hash_aware_read_dedup":{"enabled":true,"min_output_tokens":256,"timing":"after_tool_batch"},"inline_media_history":{"enabled":true,"keep_recent_images":1,"max_inline_media_bytes":524288,"timing":"after_tool_batch","trigger_inline_media_bytes":524288},"native_tool_loop_governor":{"checkpoint_interval":80,"duplicate_read_threshold":8,"enabled":true,"large_output_bytes":65536,"max_checkpoints":3,"timing":"before_turn"},"provider_error_continue":{"enabled":true,"timing":"before_turn"},"tool_call_granularity":{"enabled":false,"timing":"before_turn"},"tool_output_offloading":{"enabled":true,"max_outputs_per_turn":8,"offload_trigger_bytes":65536,"preview_chars":2000,"timing":"after_tool_batch"},"unified_resource_recall":{"enabled":true,"max_resource_bytes":4194304,"timing":"before_turn"}},"mode":"auto"}',NULL);
