INSERT INTO "lineage"."resident_execution_configuration" ("resident_id","backend_route_id","execution_settings_json","harness_config_json","quota_reserve_override_json") VALUES ('resident_db84cf5d9828','', E'{"allow_subagents":false,"approval_policy":"never","approvals_reviewer":"user","collaboration_mode":"default","model":"gpt-6.1-sol","permission_preset":"full-access","permissions":":danger-full-access","profile":"permissions:full-access","prompt_context":{"messages":[],"system_prompt":"你是Portal开源版本团队的README文档负责人。负责发行工程顶层README及其语言版本、面向新用户的项目介绍/功能范围/安装入口/配置样例引用/运行升级入口/支持平台与已验证边界/贡献入口；优先消费固定源码、真实manifest、667集成记录、e4 INSTALL与验证结果，不把局部在线或热补称为完整发行。README之外的安装器/INSTALL权威归e4，生成器与run归409，打包页面归bc，规范独立审查归977，集成归667；主线清理由原主线负责。可独立设计、编写、自检与交付自己写域，不设同伴签字门槛。未明确许可证/公开目标时只维护本地可复查文档，不公开发布数据/凭据或写出私密账号。\\n你由Steward依据原用户msg_a6c4b362793bfaa6849071c6df6aee15（请创建一个写开源版本README的resident）创建并加入Family fbi_08db325e4051。原创建请求转交给你用于交付角色入口：创建已经完成，收到该原文不得再创建Resident或团队，不重复派发。当前只确认你的职责和后续消费入口；具体README文件撰写按后续用户任务执行，不把本次成员创建解释为已授权立即重写源码文档。维护自己的工作摘要及原输入覆盖。\\n继承Family共同目标、最新指南及Portal团队必要消息规则v6：不主动发中途进展、风险或回执；整项完成且实际接收方需要最终成果时仅沿原任务/门面交付一次，不广播不抄送；旧接口变更/紧急同步许可按v6收紧。源身份、权限按当前Resident，不借用发送者。完整背景入口：Family共享目标与Steward family-work-guide.md；当前验收以固定源码/自然生成v0.7新工程为准，旧v07-live在线不代新包验证。"},"reasoning_effort":"high","runtime_settings_authority":"portal_manual","runtime_settings_authority_at":"2026-10-19T16:05:46Z","runtime_settings_authority_by":"resident_cc76524b21d7","sandbox":"danger-full-access","sandbox_explicit":true,"service_tier":"","updated_at":"2026-10-19T16:05:46Z","updated_by":"resident_cc76524b21d7"}','{"features":{"artifact_search_and_slice":{"enabled":true,"timing":"before_turn"},"early_context_compaction":{"enabled":true},"hash_aware_read_dedup":{"enabled":true,"min_output_tokens":256,"timing":"after_tool_batch"},"inline_media_history":{"enabled":true,"keep_recent_images":1,"max_inline_media_bytes":524288,"timing":"after_tool_batch","trigger_inline_media_bytes":524288},"native_tool_loop_governor":{"checkpoint_interval":80,"duplicate_read_threshold":8,"enabled":true,"large_output_bytes":65536,"max_checkpoints":3,"timing":"before_turn"},"provider_error_continue":{"enabled":true,"timing":"before_turn"},"tool_call_granularity":{"enabled":false,"timing":"before_turn"},"tool_output_offloading":{"enabled":true,"max_outputs_per_turn":8,"offload_trigger_bytes":65536,"preview_chars":2000,"timing":"after_tool_batch"},"unified_resource_recall":{"enabled":true,"max_resource_bytes":4194304,"timing":"before_turn"}},"mode":"auto"}',NULL);
