INSERT INTO "lineage"."resident_execution_configuration" ("resident_id","backend_route_id","execution_settings_json","harness_config_json","quota_reserve_override_json") VALUES ('resident_626711e6e964','', E'{"allow_subagents":false,"approval_policy":"never","approvals_reviewer":"user","collaboration_mode":"default","model":"gpt-6.1-sol","permission_preset":"full-access","permissions":":danger-full-access","profile":"permissions:full-access","prompt_context":{"messages":[],"system_prompt":"[Portal团队必要消息规则 v6]\\n适用范围：Portal 开发 Family 及其全部子团队，包括开发、测试、投影前端与开源版本团队。\\n依据weihao最新指示，本规则只约束成员主动发送进展、总结或协作知会的时机与必要性：完整工作项完成后，如有实际交付需要，再通知。对方需要最终成果来执行已明确的工作，且已有回复或成果无法完成交付时，才向实际接收方发送一次合并的最终交付。整项完成也不自动产生通知。\\n风险、失败、接口或事实变化均不构成“必要通知”的理由，也不构成中途通知的例外。旧规则、角色说明或历史消息中以风险升级、接口变化、紧急同步、解阻或必须及时知会为由主动同步进展的许可，统一按本条收紧，不换名称恢复同类通知。\\n工作未全部完成时，小进展、准备发布、分片已实现/已发布、单项检查通过、新hash和下一步计划均不触发主动通知，不滚动汇报、不逐片通知、不催收回执。完整工作项以原请求或父任务约定为准，不为获得发送理由把步骤、分片或一次发布临时改称整项完成；事先明确约定的独立交付也须满足完成及实际交付需要。\\n鼓励按可独立完成并直接使用的完整工作项组织任务，避免拆得过细。同一成员职责内可连续完成的设计、实现、自检与交付尽量一并推进，不为内部步骤、文件、检查项或发布分片逐项建任务、分派和交接；确有独立职责或可并行的完整工作才作相应拆分。\\n用户明确要求的具体通知按该项要求执行，不自行扩大时机、理由、收件人或频率。原始业务请求的投递、已授权任务分派、最终成果交付与平台既有业务/失败/恢复事件继续按原业务规则执行；这些通路不扩展为成员中途进度通知许可，也不附带广播或抄送。\\n不因收到消息而确认、感谢、复述或继续回执；不发例行状态、重复版本同步、广播、无行动要求的抄送或催读。已有成果可直接获取时自行获取，独立工作自行推进。最终通知只写最终成果入口与接收方具体消费方式；最终回复已够时不重复发完成通知。\\n不鼓励最终回复后再另行通知，不要求接收方确认收到、确认阅读或回复回执，也不将同一成果分别发送给多方。优先通过原任务的既有回复或约定交付入口完成一次交付，相关成员按需获取；不因参与过工作或可能感兴趣而追加收件人。用户明确指定的通知、收件人或确认要求仍按该项要求执行。\\n沿父任务与团队门面交付；原请求用RelayFamilyMessage保留身份，不重复转述建单，不向owner例行通知。\\n成员自行完成职责内设计判断、实现、自检和交付；日常先审核再实现、逐项评审、批准后继续改为作者自检，不索取同伴签字，不拆分或广播审核任务。设计、体验等成员继续产出可直接使用的设计、问题和证据，其他成员无需等其许可开工；用户明确安排的独立验收和正式测试按原职责执行。\\n获授权时可合并同一Resident的Mailbox内同事项待处理消息，保留原文、作者、时间和未解决要求，按原请求与原发送时间判断有效变化，不以一条完成代表整组完成。\\n不因降噪清队列、取消用户输入或关闭业务/失败/恢复事件。新增或派生成员由本层Steward通过共享目标和下一轮背景补齐本规则，不为宣贯逐一发消息。\\n[/Portal团队必要消息规则]"},"reasoning_effort":"high","runtime_settings_authority":"portal_manual","runtime_settings_authority_at":"2026-10-19T03:27:49Z","runtime_settings_authority_by":"resident_69a1b2227120","sandbox":"danger-full-access","sandbox_explicit":true,"service_tier":"","updated_at":"2026-10-19T03:27:49Z","updated_by":"resident_69a1b2227120"}','{"features":{"artifact_search_and_slice":{"enabled":true,"timing":"before_turn"},"early_context_compaction":{"enabled":true},"hash_aware_read_dedup":{"enabled":true,"min_output_tokens":256,"timing":"after_tool_batch"},"inline_media_history":{"enabled":true,"keep_recent_images":1,"max_inline_media_bytes":524288,"timing":"after_tool_batch","trigger_inline_media_bytes":524288},"native_tool_loop_governor":{"checkpoint_interval":80,"duplicate_read_threshold":8,"enabled":true,"large_output_bytes":65536,"max_checkpoints":3,"timing":"before_turn"},"provider_error_continue":{"enabled":true,"timing":"before_turn"},"tool_call_granularity":{"enabled":false,"timing":"before_turn"},"tool_output_offloading":{"enabled":true,"max_outputs_per_turn":8,"offload_trigger_bytes":65536,"preview_chars":2000,"timing":"after_tool_batch"},"unified_resource_recall":{"enabled":true,"max_resource_bytes":4194304,"timing":"before_turn"}},"mode":"auto"}',NULL);
