INSERT INTO "templates"."templates" ("template_id","kind","category","title","description","targets","parameters","body","builtin_key","builtin_source","version","created_at","created_by","updated_at","updated_by") VALUES ('template_cda267fe3c57','structure','structure','Agent Loop','目标完成一轮后由评审检查；未完成时把意见发回目标，DONE 或轮数上限结束循环。','["resident"]'::jsonb, E'[{"name": "role", "type": "enum", "default": "critic", "options": ["critic", "questioner", "ideator", "supervisor"], "required": false, "description": "\\u8bc4\\u5ba1\\u3001\\u63d0\\u95ee\\u3001\\u6784\\u601d\\u6216\\u76d1\\u7763\\u804c\\u8d23"}, {"name": "max_rounds", "type": "integer", "default": 5, "required": false, "description": ""}, {"name": "task", "type": "text", "default": "\\u68c0\\u67e5\\u76ee\\u6807 Resident \\u6700\\u8fd1\\u4e00\\u8f6e\\u7684\\u7ed3\\u679c\\u3002\\u6309\\u4f60\\u7684\\u804c\\u8d23\\u63d0\\u51fa\\u5177\\u4f53\\u4fee\\u6539\\uff1b\\u76ee\\u6807\\u5b8c\\u6210\\u65f6\\u53ea\\u56de\\u590d DONE\\u3002", "required": false, "description": ""}]'::jsonb, E'{"match": [], "roles": [{"key": "target", "from": "target", "description": "\\u88ab\\u63a8\\u8fdb\\u7684 Resident"}, {"key": "reviewer", "from": "new", "title": "{{role.target.title}} \\u00b7 {{param.role}}", "provider": "codex", "settings": {}}], "wires": [{"key": "watch_target", "kind": "watch", "source": "target_done", "target": "target", "source_port": "watch"}, {"key": "count_round", "kind": "route", "source": "target_done", "target": "rounds"}, {"key": "ask_reviewer", "kind": "route", "config": {"invoke_profiles": {"agent": {"arguments": {"prompt": {"concat": [{"value": "\\u4f60\\u5728\\u5faa\\u73af\\u4e2d\\u7684\\u804c\\u8d23\\u662f {{param.role}}\\uff08critic \\u627e\\u95ee\\u9898\\uff0cquestioner \\u63d0\\u95ee\\u9898\\uff0cideator \\u63d0\\u60f3\\u6cd5\\uff0csupervisor \\u7763\\u4fc3\\u5b8c\\u6210\\uff09\\u3002"}, {"value": "{{param.task}}"}], "separator": "\\n\\n"}}}}}, "source": "rounds", "target": "reviewer", "source_port": "continue"}, {"key": "review_open", "kind": "route", "source": "reviewer", "target": "not_done"}, {"key": "review_done", "kind": "route", "source": "reviewer", "target": "is_done"}, {"key": "send_back", "kind": "route", "config": {"invoke_profiles": {"agent": {"arguments": {"prompt": {"from": "packet.message.text", "default": ""}}}}}, "source": "not_done", "target": "target"}, {"key": "finish", "kind": "route", "source": "is_done", "target": "rounds", "target_port": "done"}], "components": [{"key": "target_done", "kind": "event_source", "title": "\\u76ee\\u6807\\u5b8c\\u6210\\u4e00\\u8f6e", "config": {"event_type": "resident.work_finished"}}, {"key": "rounds", "kind": "loop", "title": "\\u8f6e\\u6570", "config": {"completion": "rearm", "max_rounds": "{{param.max_rounds}}"}}, {"key": "not_done", "kind": "filter", "title": "\\u672a\\u5b8c\\u6210", "config": {"selection": {"mode": "all", "limit": null, "order_by": "input", "conditions": [{"from": "packet.message.text", "value": "DONE", "operator": "not_contains"}]}, "operator_implementation": "rules"}}, {"key": "is_done", "kind": "filter", "title": "\\u5df2\\u5b8c\\u6210", "config": {"selection": {"mode": "all", "limit": null, "order_by": "input", "conditions": [{"from": "packet.message.text", "value": "DONE", "operator": "contains"}]}, "operator_implementation": "rules"}}], "function_block": true}'::jsonb,'agent_loop','44f4e926c4c48dde8cc9fe1037c4b7fac0762907b9d4ccc1634c7fc32ac0b02b',4,'2026-10-13 20:17:16.521770+08:00'::timestamptz,'portal','2026-10-14 21:42:42.697360+08:00'::timestamptz,'tfi-exported-user');
INSERT INTO "templates"."templates" ("template_id","kind","category","title","description","targets","parameters","body","builtin_key","builtin_source","version","created_at","created_by","updated_at","updated_by") VALUES ('template_0fe25d6e7623','structure','structure','固定提醒','目标每完成一轮就发送同一条提示词，由循环组件限制次数。','["resident"]'::jsonb, E'[{"name": "message", "type": "text", "default": "\\u8bf7\\u7ee7\\u7eed\\u63a8\\u8fdb\\u5f53\\u524d\\u4efb\\u52a1\\uff0c\\u5e76\\u8bf4\\u660e\\u672c\\u8f6e\\u8fdb\\u5c55\\u3002", "required": false, "description": ""}, {"name": "max_rounds", "type": "integer", "default": 5, "required": false, "description": ""}]'::jsonb, E'{"match": [], "roles": [{"key": "target", "from": "target", "description": "\\u88ab\\u63a8\\u8fdb\\u7684 Resident"}], "wires": [{"key": "watch_target", "kind": "watch", "source": "target_done", "target": "target", "source_port": "watch"}, {"key": "count_round", "kind": "route", "source": "target_done", "target": "rounds"}, {"key": "fire", "kind": "route", "config": {"include_envelope": false}, "source": "rounds", "target": "remind", "source_port": "continue"}, {"key": "remind_target", "kind": "target", "source": "remind", "target": "target", "source_port": "target"}], "components": [{"key": "target_done", "kind": "event_source", "title": "\\u76ee\\u6807\\u5b8c\\u6210\\u4e00\\u8f6e", "config": {"event_type": "resident.work_finished"}}, {"key": "rounds", "kind": "loop", "title": "\\u8f6e\\u6570", "config": {"completion": "rearm", "max_rounds": "{{param.max_rounds}}"}}, {"key": "remind", "kind": "effect", "title": "\\u53d1\\u9001\\u63d0\\u9192", "config": {"script": "DeliverMessage resident_id=\\"${endpoint.target}\\" message=\\"{{param.message}}\\"", "endpoints": ["target"]}}], "function_block": true}'::jsonb,'fixed_reminder','2df33b36602751500bc1d8d9ecc2c315c8dd9cf3281d2e829937f6f816b1cfc4',6,'2026-10-13 20:17:16.522448+08:00'::timestamptz,'portal','2026-10-14 21:42:42.697360+08:00'::timestamptz,'tfi-exported-user');
INSERT INTO "templates"."templates" ("template_id","kind","category","title","description","targets","parameters","body","builtin_key","builtin_source","version","created_at","created_by","updated_at","updated_by") VALUES ('template_95209661c0ea','structure','structure','定时工作','按周期推进目标 Resident，也可以从“运行一次”手动触发。','["resident"]'::jsonb, E'[{"name": "task", "type": "text", "required": true, "description": "\\u6bcf\\u6b21\\u8981\\u505a\\u7684\\u5de5\\u4f5c"}, {"name": "interval_seconds", "type": "duration", "default": 3600, "required": false, "description": ""}, {"name": "jitter_seconds", "type": "integer", "default": 0, "required": false, "description": ""}]'::jsonb, E'{"match": [], "roles": [{"key": "target", "from": "target", "description": "\\u88ab\\u63a8\\u8fdb\\u7684 Resident"}], "wires": [{"key": "scheduled", "kind": "route", "config": {"invoke_profiles": {"agent": {"arguments": {"prompt": {"value": "{{param.task}}"}}}}}, "source": "timer", "target": "target"}, {"key": "on_demand", "kind": "route", "config": {"invoke_profiles": {"agent": {"arguments": {"prompt": {"concat": [{"value": "{{param.task}}"}, {"from": "event.payload.prompt", "default": ""}], "separator": "\\n\\n"}}}}}, "source": "manual", "target": "target"}], "components": [{"key": "timer", "kind": "event_source", "title": "\\u5b9a\\u65f6", "config": {"event_type": "time.reached", "schedule_mode": "recurring", "jitter_seconds": "{{param.jitter_seconds}}", "misfire_policy": "coalesce_latest", "overlap_policy": "drop", "recurrence_kind": "interval", "interval_seconds": "{{param.interval_seconds}}"}}, {"key": "manual", "kind": "event_source", "title": "\\u8fd0\\u884c\\u4e00\\u6b21", "config": {"event_type": "manual.triggered"}}], "function_block": true}'::jsonb,'scheduled_work','1deeda9234af80c57a4f078139c7cfa808cdc0292518daca21dd1dbe99a6b94f',3,'2026-10-13 20:17:16.523621+08:00'::timestamptz,'portal','2026-10-14 21:42:42.697360+08:00'::timestamptz,'tfi-exported-user');
INSERT INTO "templates"."templates" ("template_id","kind","category","title","description","targets","parameters","body","builtin_key","builtin_source","version","created_at","created_by","updated_at","updated_by") VALUES ('template_333e72d023a8','structure','structure','Leader Pulse','周期性向 Lineage Leader 发送进展检查任务。','["canvas"]'::jsonb, E'[{"name": "interval_seconds", "type": "duration", "default": 900, "required": false, "description": ""}, {"name": "prompt", "type": "text", "default": "\\u68c0\\u67e5\\u8fd9\\u4e2a Lineage \\u7684\\u8282\\u70b9\\u72b6\\u6001\\u3001\\u6700\\u8fd1\\u7ed3\\u679c\\u4e0e Workspace \\u53d8\\u5316\\uff0c\\u5f52\\u7eb3\\u963b\\u585e\\u3001\\u504f\\u822a\\u4e0e\\u4e0b\\u4e00\\u6b65\\u534f\\u8c03\\u4e8b\\u9879\\uff0c\\u5fc5\\u8981\\u65f6\\u7ed9\\u6210\\u5458\\u6d3e\\u6d3b\\u3002", "required": false, "description": ""}]'::jsonb, E'{"match": [], "roles": [{"key": "leader", "from": "lineage_leader"}], "wires": [{"key": "check", "kind": "route", "config": {"include_envelope": false}, "source": "pulse", "target": "send"}, {"key": "leader_target", "kind": "target", "source": "send", "target": "leader", "source_port": "target"}], "components": [{"key": "pulse", "kind": "event_source", "title": "\\u5468\\u671f\\u68c0\\u67e5", "config": {"event_type": "time.reached", "schedule_mode": "recurring", "misfire_policy": "coalesce_latest", "overlap_policy": "drop", "recurrence_kind": "interval", "interval_seconds": "{{param.interval_seconds}}"}}, {"key": "send", "kind": "effect", "title": "\\u53d1\\u9001\\u68c0\\u67e5\\u4efb\\u52a1", "config": {"script": "DeliverMessage resident_id=\\"${endpoint.target}\\" message=\\"{{param.prompt}}\\"", "endpoints": ["target"]}}], "function_block": true}'::jsonb,'leader_pulse','fea63fea1faed567129b61388898cbc5ecb300d9e07ef3982c21680bb40cb7ef',3,'2026-10-13 20:17:16.524491+08:00'::timestamptz,'portal','2026-10-14 21:42:42.697360+08:00'::timestamptz,'tfi-exported-user');
